import { useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { ABOUT_LINKS } from '@/features/settings/about.js';
import { t } from '@/i18n/index.js';
import styles from './consent.module.css';

/**
 * The question asked before anything goes to the AI provider; opened by
 * `ensureAiConsent` in consent.tsx, never by itself.
 */
export function AiConsentSheet({ onAnswer }: { onAnswer: (allowed: boolean) => void }): React.JSX.Element {
  const [answered, setAnswered] = useState(false);
  const answer = (allowed: boolean): void => {
    if (answered) return;
    setAnswered(true);
    onAnswer(allowed);
  };
  return (
    <Sheet
      title={t('aiConsent.title')}
      onClose={() => {
        answer(false);
      }}
    >
      <div className={styles.body}>
        <p className={styles.lead}>{t('aiConsent.lead')}</p>
        <p className={styles.note}>{t('aiConsent.what')}</p>
        <p className={styles.note}>{t('aiConsent.never')}</p>
        <p className={styles.note}>
          <a href={ABOUT_LINKS.privacy} target="_blank" rel="noopener noreferrer">
            {t('aiConsent.privacy')}
          </a>
        </p>
        <div className={styles.actions}>
          <Button
            size="large"
            block
            onClick={() => {
              answer(true);
            }}
          >
            {t('aiConsent.allow')}
          </Button>
          <Button
            variant="secondary"
            size="large"
            block
            onClick={() => {
              answer(false);
            }}
          >
            {t('aiConsent.notNow')}
          </Button>
        </div>
      </div>
    </Sheet>
  );
}
