/**
 * Asking once before anything goes to an AI provider.
 *
 * App Store Review Guideline 5.1.2(i) (November 2025) asks an app to say
 * plainly when personal data goes to a third-party AI and to get the
 * person's permission first; Google Play's User Data policy asks for a
 * prominent disclosure before the same kind of transfer. Every request that
 * hands the learner's text to the model goes through `withAiConsent` in the
 * API layer (cards, Words worth keeping, Lex, Use it in a sentence), so no
 * screen can forget to ask.
 *
 * The answer is kept in the device's small preferences store, like the
 * introduction's: it is a decision about this device's app, it is made
 * before anything else loads, and signing out must not ask again. "Not now"
 * is not remembered: the next AI tap asks again, because that tap is the
 * learner asking for the AI.
 */
import { createRoot } from 'react-dom/client';
import { ApiError } from '@/api/errors.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import { AiConsentSheet } from './AiConsentSheet.js';

const KEY = 'wb.aiConsent';
/**
 * The wording a stored yes was given to. '1' was the sheet that named one
 * provider (OpenAI); '2' is the one that points to the providers in the
 * privacy policy (21 Oct 2026). A yes to older wording asks again, so raise
 * this whenever what the learner agrees to changes.
 */
const ALLOWED = '2';

/** The code a declined request carries, so a screen can tell it from a failure. */
export const AI_CONSENT_DECLINED = 'ai_consent_declined';

/** Whether this device has allowed sending text to the AI providers. */
export function aiConsentGiven(): boolean {
  return platform.prefs.get(KEY) === ALLOWED;
}

/** Records the learner's yes. */
export function giveAiConsent(): void {
  platform.prefs.set(KEY, ALLOWED);
}

/** Whether an error is the learner saying "not now" to the AI. */
export function isAiConsentDeclined(cause: unknown): boolean {
  return cause instanceof ApiError && cause.code === AI_CONSENT_DECLINED;
}

// One question at a time: two AI taps in a row share the same sheet.
let pending: Promise<boolean> | undefined;

/** Shows the question and answers what the learner chose. */
function ask(): Promise<boolean> {
  if (typeof document === 'undefined') return Promise.resolve(false);
  pending ??= new Promise<boolean>((resolve) => {
    const host = document.createElement('div');
    document.body.appendChild(host);
    const root = createRoot(host);
    const finish = (allowed: boolean): void => {
      if (allowed) giveAiConsent();
      pending = undefined;
      // Unmounted after the click has finished, so the sheet's own focus
      // handling runs against a live tree.
      setTimeout(() => {
        root.unmount();
        host.remove();
      }, 0);
      resolve(allowed);
    };
    root.render(<AiConsentSheet onAnswer={finish} />);
  });
  return pending;
}

/**
 * Resolves once the learner has allowed AI on this device, asking first if
 * they have not; rejects with an `ai_consent_declined` ApiError if they say
 * no, so the request is never sent.
 */
export async function ensureAiConsent(): Promise<void> {
  if (aiConsentGiven()) return;
  if (await ask()) return;
  // The message is the learner's own words: several screens show an
  // ApiError's message as it is.
  throw new ApiError('forbidden', t('aiConsent.declined'), 0, {
    type: 'about:blank',
    title: 'AI not allowed',
    status: 0,
    code: AI_CONSENT_DECLINED,
  });
}

/** Runs a request that sends the learner's text to the model, asking first. */
export async function withAiConsent<T>(request: () => Promise<T>): Promise<T> {
  await ensureAiConsent();
  return request();
}
